"""Evaluation helpers. Every function takes the anomaly scores first and the
labels second, so labels are consumed only after predictions exist (R9, R10)."""
from __future__ import annotations

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score


def roc_auc(scores, y_true) -> float:
    return float(roc_auc_score(np.asarray(y_true), np.asarray(scores, dtype=np.float64)))


def auc_pr(scores, y_true) -> float:
    """Primary AUC-PR: sklearn average_precision (ADBench convention)."""
    return float(average_precision_score(np.asarray(y_true), np.asarray(scores, dtype=np.float64)))


def auc_pr_trapz(scores, y_true) -> float:
    """Secondary AUC-PR: trapezoidal integral of the PR curve."""
    p, r, _ = precision_recall_curve(np.asarray(y_true), np.asarray(scores, dtype=np.float64))
    return float(np.trapz(p, r))


def summarize(values) -> dict:
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "std_pop": float(v.std(ddof=0)),
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

