def build_metrics(c1, c2, best_m, summ, prov, records, scale, total, ref=None):
    """Assemble results/metrics.json.

    Every reported number is produced by SVEAD running on the cardio table.  The
    published values of the claims are read from state/claim_contract.json by
    load_reference_targets() and enter only this reporting layer.
    """
    ref = ref or {}
    claims = ref.get("claims") or {}
    tol_default = ref.get("tolerance")

    def _cmp(claim_id, got, fallback_spread):
        c = claims.get(claim_id) or {}
        paper = c.get("value")
        if paper is None:
            return {"paper_value": None, "reproduced": got, "abs_difference": None,
                    "tolerance": None, "within_tolerance": None,
                    "note": "claim contract unavailable - no comparison made"}
        spread = c.get("reported_std") or fallback_spread
        tol = tol_default if (tol_default and claim_id == "C1") else (3 * spread if spread else None)
        d = abs(got - paper)
        return {
            "paper_value": paper, "paper_metric": c.get("metric"),
            "paper_dataset": c.get("dataset"), "paper_statement": c.get("statement"),
            "reproduced": got,
            "std_over_5_repeats": c1["std"] if claim_id == "C1" else c2["std"],
            "per_repeat": c1["values"] if claim_id == "C1" else c2["values"],
            "abs_difference": d, "tolerance": tol, "paper_reported_std": c.get("reported_std"),
            "within_tolerance": bool(d <= tol) if tol is not None else None,
        }

    cc1 = _cmp("C1", c1["mean"], 0.0063)
    cc2 = _cmp("C2", c2["mean"], 0.0246)
    if cc1["paper_value"] is None:
        verdict = "NOT COMPARABLE - state/claim_contract.json unavailable"
    else:
        verdict = ("%s - reproduced AUC-ROC %.4f vs published %.4f (|diff| %.4f %s tol %.4f)"
                   % ("PASS" if cc1["within_tolerance"] else "FAIL", c1["mean"],
                      cc1["paper_value"], cc1["abs_difference"],
                      "<=" if cc1["within_tolerance"] else ">", cc1["tolerance"]))
    c5 = None
    if scale is not None:
        c5 = dict(scale)
        c5["comparison"] = _cmp("C5", scale["seconds_total"], None)
        c5["comparison"].pop("per_repeat", None)
        c5["comparison"].pop("std_over_5_repeats", None)
        c5["note"] = ("measured on this machine's CPU, not the paper's Ryzen 9 9950X; "
                      "reported as a measurement, not a verdict")
    return {

def _cmp(claim_id, got, our_std):
    """Compare a reproduced number with the published one (contract file only).

    Tolerance: the contract's absolute tolerance for C1, else 3x the published
    5-run std if the contract carries one, else 3x our own measured std.
    """
    c = claims.get(claim_id) or {}
    paper = c.get("value")
    if paper is None:
        return {"paper_value": None, "reproduced": got, "abs_difference": None,
                "tolerance": None, "within_tolerance": None,
                "note": "claim contract unavailable - no comparison made"}
    spread = c.get("reported_std")
    if tol_default is not None and claim_id == "C1":
        tol = tol_default
    elif spread:
        tol = 3 * spread
    else:
        tol = 3 * our_std
    d = abs(got - paper)
    return {
        "paper_value": paper, "paper_metric": c.get("metric"),
        "paper_dataset": c.get("dataset"), "paper_statement": c.get("statement"),
        "reproduced": got,
        "std_over_5_repeats": our_std,
        "per_repeat": (c1["values"] if claim_id == "C1" else c2["values"]),
        "abs_difference": d, "tolerance": tol, "paper_reported_std": spread,
        "tolerance_origin": ("contract tolerance" if (tol_default is not None and claim_id == "C1")
                             else "3x published std" if spread else "3x measured std"),
        "within_tolerance": bool(d <= tol),
    }

cc1 = _cmp("C1", c1["mean"], c1["std"])
cc2 = _cmp("C2", c2["mean"], c2["std"])

